// src/utils/sfx.js
//
// Small helper for the short game sound effects. Every file lives in
// public/sounds and is generated by frontend/scripts/generate-sounds.mjs.
//
// Three rules keep audio from ever being a problem:
//   * playback failures are swallowed - browsers block autoplay until the user
//     has interacted, and that must never surface as an error;
//   * volumes are set explicitly per effect, because these sounds are meant to sit
//     under the music rather than compete with it;
//   * every effect is tracked, so it can be stopped cleanly when the page goes
//     away. Tearing down a media element mid-playback is what produced an audible
//     pop when the page was reloaded right after opening a case.
import { asset } from "./assetUrl.js";

// Every effect created here, so nothing is left running when the page unloads.
const registry = new Set();

/** Create an effect from a public/ path with its own volume (0..1). */
export const createSfx = (path, volume = 0.4) => {
  const audio = new Audio(asset(path));
  audio.volume = Math.min(1, Math.max(0, volume));
  audio.preload = "auto";
  registry.add(audio);
  return audio;
};

/**
 * Stop and rewind every effect. Called when the page is hidden or unloaded so the
 * browser is not left destroying a media element mid-sample, which cracks through
 * the speakers as a pop.
 */
export const stopAllSfx = () => {
  registry.forEach((audio) => {
    try {
      if (!audio.paused) audio.pause();
      audio.currentTime = 0;
    } catch {
      // Nothing to do: the element may already be detached.
    }
  });
};

if (typeof window !== "undefined") {
  window.addEventListener("pagehide", stopAllSfx);
  window.addEventListener("beforeunload", stopAllSfx);
}

/** Play an effect from the start, ignoring anything the browser refuses. */
export const playSfx = (audio) => {
  if (!audio) return;
  try {
    audio.currentTime = 0;
    const played = audio.play();
    if (played && typeof played.catch === "function") played.catch(() => {});
  } catch {
    // A sound is a nice-to-have; never let it interfere with the game.
  }
};

export default playSfx;
